package rules

import "testing"

// Cases ported from PHP-CS-Fixer's GeneralAttributeRemoveFixerTest, with
// byte-exact output from PHP-CS-Fixer 3.95. The default (empty attributes list)
// removes nothing.
func TestGeneralAttributeRemovePhpCsFixerCases(t *testing.T) {
	t.Parallel()
	aliasRunUpstreamCases(t, GeneralAttributeRemove{}, []aliasUpstreamCase{
		{"Explicit in namespace", map[string]any{"attributes": []any{"A\\B\\Bar", "Test\\A\\B\\Quux"}}, "<?php\n            namespace Test;\n\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            #[Foo(4, 'baz qux')]\n            #[BarAlias(3)]\n            #[AB\\Baz(prop: 'baz')]\n            #[\\A\\B\\Qux()]\n            #[A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar')]\n            #[Corge]\n            function f() {}\n            ", "<?php\n            namespace Test;\n\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            #[Foo(4, 'baz qux')]\n            #[AB\\Baz(prop: 'baz')]\n            #[\\A\\B\\Qux()]\n            #[Corge]\n            function f() {}\n            "},
		{"Explicit in global namespace", map[string]any{"attributes": []any{"\\A\\B\\Qux", "\\Corge", "A\\B\\Bar"}}, "<?php\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            #[A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar')]\n            #[BarAlias(3)]\n            #[AB\\Baz(prop: 'baz')]\n            #[Foo(4, 'baz qux')]\n            #[\\A\\B\\Qux()]\n            #[Corge]\n            function f() {}\n            ", "<?php\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            #[A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar')]\n            #[AB\\Baz(prop: 'baz')]\n            #[Foo(4, 'baz qux')]\n            function f() {}\n            "},
		{"Multiple namespaces", map[string]any{"attributes": []any{"A\\B\\Bar", "Test\\AB\\Baz", "A\\B\\Quux", "A\\B\\Baz", "A\\B\\Foo", "\\AB\\Baz"}}, "<?php\n            namespace Test\n            {\n                use A\\B\\Foo;\n                use A\\B\\Bar as BarAlias;\n\n                #[AB\\Baz(prop: 'baz')]\n                #[Foo(4, 'baz qux')]\n                #[BarAlias(3)]\n                function f() {}\n            }\n\n            namespace Test2\n            {\n                use A\\B\\Bar as BarAlias;\n                use A\\B as AB;\n\n                #[BarAlias(3)]\n                #[AB\\Baz(prop: 'baz')]\n                #[\\A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar')]\n                function f() {}\n            }\n\n            namespace Test\n            {\n                use A\\B\\Foo;\n                use A\\B\\Bar as BarAlias2;\n\n                #[AB\\Baz(prop: 'baz')]\n                #[Foo(4, 'baz qux')]\n                #[BarAlias2(3)]\n                function f2() {}\n            }\n\n            namespace\n            {\n                use A\\B\\Foo;\n                use A\\B\\Bar as BarAlias3;\n\n                #[AB\\Baz(prop: 'baz')]\n                #[Foo(4, 'baz qux')]\n                #[BarAlias3(3)]\n                function f() {}\n            }\n            ", "<?php\n            namespace Test\n            {\n                use A\\B\\Foo;\n                use A\\B\\Bar as BarAlias;\n\n                function f() {}\n            }\n\n            namespace Test2\n            {\n                use A\\B\\Bar as BarAlias;\n                use A\\B as AB;\n\n                #[\\A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar')]\n                function f() {}\n            }\n\n            namespace Test\n            {\n                use A\\B\\Foo;\n                use A\\B\\Bar as BarAlias2;\n\n                function f2() {}\n            }\n\n            namespace\n            {\n                use A\\B\\Foo;\n                use A\\B\\Bar as BarAlias3;\n\n                function f() {}\n            }\n            "},
		{"With whitespaces", map[string]any{"attributes": []any{"A\\B\\Foo", "Test\\A\\B\\Quux", "A\\B\\Baz"}}, "<?php\n            namespace Test;\n\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            #[   AB\\Baz   (prop: 'baz')   ]\n            #[   A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar')   ]\n            #[   \\A\\B\\Qux()   ]\n            #[   BarAlias   (3)   ]\n            #[   Corge   ]\n            #[   Foo   (4, 'baz qux')   ]\n            function f() {}\n            ", "<?php\n            namespace Test;\n\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            #[   \\A\\B\\Qux()   ]\n            #[   BarAlias   (3)   ]\n            #[   Corge   ]\n            function f() {}\n            "},
		{"With docblock", map[string]any{"attributes": []any{"Test\\Corge", "\\A\\B\\Qux"}}, "<?php\n            namespace Test;\n\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            /**\n             * Start docblock\n             */\n            /**\n             * AB\\Baz docblock\n             */\n            #[AB\\Baz(prop: 'baz')]\n            #[A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar')]\n            #[\\A\\B\\Qux()]\n            #[BarAlias(3)]\n            /**\n             * Corge docblock\n             */\n            #[Corge]\n            #[Foo(4, 'baz qux')]\n            /**\n             * End docblock\n             */\n            class X\n            {}\n\n            function f2(/** Start docblock */#[Foo(4, 'baz qux')] #[BarAlias(3)] #[\\A\\B\\Qux()] /** Corge docblock */#[Corge] /** End docblock */string $param) {}\n            ", "<?php\n            namespace Test;\n\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            /**\n             * Start docblock\n             */\n            /**\n             * AB\\Baz docblock\n             */\n            #[AB\\Baz(prop: 'baz')]\n            #[A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar')]\n            #[BarAlias(3)]\n            #[Foo(4, 'baz qux')]\n            /**\n             * End docblock\n             */\n            class X\n            {}\n\n            function f2(/** Start docblock */#[Foo(4, 'baz qux')] #[BarAlias(3)] /** End docblock */string $param) {}\n            "},
		{"With comments", map[string]any{"attributes": []any{"Test\\A\\B\\Quux", "A\\B\\Bar", "Test\\Corge", "A\\B\\Baz", "A\\B\\Foo", "\\A\\B\\Qux"}}, "<?php\n            namespace Test;\n\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            #[/* comment */A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar') /* comment */]\n            #[ /* comment */ BarAlias/* comment */(3)/* comment */]\n            #[/* comment */ Corge/* comment */]\n            #[/* comment */AB\\Baz /* comment */ (prop: 'baz') /* comment */ ]\n            #[/* comment */Foo/* comment */(4, 'baz qux') /* comment */ ]\n            #[   /* comment */   \\A\\B\\Qux()/* comment */]\n            function f() {}\n            ", "<?php\n            namespace Test;\n\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            function f() {}\n            "},
		{"With multiple attributes", map[string]any{"attributes": []any{"A\\B\\Foo", "\\A\\B\\Qux"}}, "<?php\n            namespace Test;\n\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            #[\n                AB\\Baz(prop: 'baz'),\n                A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar'),\n                \\A\\B\\Qux(),\n                BarAlias(3),\n                Corge,\n                Foo(4, 'baz qux'),\n            ]\n            class X\n            {\n                #[ AB\\Baz(prop: 'baz'), A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar'), \\A\\B\\Qux(), BarAlias(3), Corge,Foo(4, 'baz qux')]\n                public function y() {}\n            }\n            ", "<?php\n            namespace Test;\n\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            #[\n                AB\\Baz(prop: 'baz'),\n                A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar'),\n                BarAlias(3),\n                Corge\n            ]\n            class X\n            {\n                #[ AB\\Baz(prop: 'baz'), A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar'), BarAlias(3), Corge]\n                public function y() {}\n            }\n            "},
		{"Multiline with no trailing comma", map[string]any{"attributes": []any{"A\\B\\Foo", "\\A\\B\\Qux", "A\\B\\Baz", "Test\\A\\B\\Quux", "A\\B\\Bar", "Test\\Corge"}}, "<?php\n            namespace Test;\n\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            #[\n                AB\\Baz(prop: 'baz'),\n                A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar'),\n                \\A\\B\\Qux(),\n                BarAlias(3),\n                Corge,\n                Foo(4, 'baz qux')\n            ]\n            class X\n            {}\n            ", "<?php\n            namespace Test;\n\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            class X\n            {}\n            "},
		{"Multiple with comments", map[string]any{"attributes": []any{"A\\B\\Foo", "Test\\Corge"}}, "<?php\n            namespace Test;\n\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            #[\n                /*\n                 * AB\\Baz comment\n                 */\n                AB\\Baz(prop: 'baz'),\n                A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar'),\n                \\A\\B\\Qux(),\n                BarAlias(3),\n                /*\n                 * Corge comment\n                 */\n                Corge,\n                /**\n                 * Foo docblock\n                 */\n                Foo(4, 'baz qux'),\n            ]\n            class X\n            {\n                #[ /* AB\\Baz comment */AB\\Baz(prop: 'baz'), A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar'), \\A\\B\\Qux(), BarAlias(3), /* Corge comment */Corge,/** Foo docblock */Foo(4, 'baz qux')]\n                public function y() {}\n            }\n            ", "<?php\n            namespace Test;\n\n            use A\\B\\Foo;\n            use A\\B\\Bar as BarAlias;\n            use A\\B as AB;\n\n            #[\n                /*\n                 * AB\\Baz comment\n                 */\n                AB\\Baz(prop: 'baz'),\n                A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar'),\n                \\A\\B\\Qux(),\n                BarAlias(3)\n            ]\n            class X\n            {\n                #[ /* AB\\Baz comment */AB\\Baz(prop: 'baz'), A\\B\\Quux(prop1: [1, 2, 4], prop2: true, prop3: 'foo bar'), \\A\\B\\Qux(), BarAlias(3)]\n                public function y() {}\n            }\n            "},
	})
}
